WITH parsed AS (SELECT id, effective_from, currency, tier_limits, tier_prices, discounts, AGGREGATE(tier_prices, 0D, (acc, p) -> acc + p, acc -> ROUND(acc / SIZE(tier_prices), 2)) AS avg_tier_price, TRANSFORM(tier_prices, (p, i) -> ROUND(p * tier_limits[i], 2)) AS tier_revenue_caps, ELEMENT_AT(tier_prices, 1) AS entry_price FROM price_tiers) SELECT currency, SUM(CASE WHEN currency = 'THB' THEN avg_tier_price ELSE 0 END) AS thb_avg_tier_price, ROUND(AVG(entry_price), 2) AS avg_entry_price, ROUND(SUM(avg_tier_price) / NULLIF(COUNT(CASE WHEN currency = 'EUR' THEN 1 END), 0), 2) AS avg_tier_price_per_eur, COUNT(*) AS event_count, COUNT(*) AS event_count_2, COUNT_IF(currency = 'THB') AS thb_events FROM parsed GROUP BY currency ORDER BY thb_avg_tier_price NULLS LAST;
